function domainCheckout(hosting,mode){return `<div id="paid-domain-help" ${mode==='new_domain'?'':'hidden'}><p><a class="secondary" href="${hosting.connected?'https://dash.cloudflare.com/'+encodeURIComponent(hosting.accountId)+'/domains/registrations':'https://dash.cloudflare.com/'}" target="_blank" rel="noopener noreferrer">Choose & register domain in Cloudflare ↗</a></p><p class="modal-note">Review the name, registration price and renewal price and complete checkout in Cloudflare. Return here afterward; SOMAS checks for the active domain automatically.</p></div>`}
function userManagementInfo(user){const d=user.details||{};return `<section class="publication-panel"><h3>User information & hosting</h3><p>${user.hosting?'Cloudflare connection verified '+new Date(user.hosting.updated).toLocaleString():'Cloudflare account setup has not been verified.'}</p>${user.hosting?`<p>Account ID: <code>${esc(user.hosting.account_id)}</code><br>Hosting address: ${user.hosting.workers_subdomain?esc(user.hosting.workers_subdomain)+'.workers.dev':'Not configured'}</p>`:''}<form id="user-details-form" data-user="${esc(user.id)}"><div class="field"><label for="user-label">Management display name</label><input id="user-label" maxlength="100" value="${esc(d.label||'')}"></div><div class="field"><label for="user-organization">Organization</label><input id="user-organization" maxlength="150" value="${esc(d.organization||'')}"></div><div class="field"><label for="user-notes">Private management notes</label><textarea id="user-notes" maxlength="2000" rows="3">${esc(d.notes||'')}</textarea></div><p class="modal-note">These fields are visible to human administrators. The verified sign-in identity and Cloudflare credentials are managed separately.</p><button class="secondary" type="submit">Save user information</button></form></section>`}
