async function hostingPage(){const epoch=routeEpoch,x=await api('hosting');if(epoch!==routeEpoch)return;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="connect-box membership-box"><span class="overline">GUIDED CLOUDFLARE SETUP</span><h1>Let’s put your project online.</h1><p>SOMAS helps you create or connect a Cloudflare account, create a website address, and publish your project. Root keeps your user record and Subnet Manager connection.</p><div class="hosting-steps"><section><span class="overline">STEP 1</span><h2>Create your Cloudflare account</h2><p>Open Cloudflare, create an account and verify your email there. Already have an account? Sign in to it.</p><a class="primary" href="https://dash.cloudflare.com/sign-up" target="_blank" rel="noopener noreferrer">Create Cloudflare account ↗</a><a class="text-button" href="https://dash.cloudflare.com/" target="_blank" rel="noopener noreferrer">Sign in to Cloudflare ↗</a><p class="modal-note">Your Cloudflare password and verification codes stay with Cloudflare.</p></section><section><span class="overline">STEP 2</span><h2>Allow SOMAS to deploy</h2><p>In Cloudflare, open Workers & Pages and finish its setup. Copy your Account ID, then create a scoped API token below.</p><a class="secondary" href="https://dash.cloudflare.com/" target="_blank" rel="noopener noreferrer">Open Workers & Pages ↗</a><a class="text-button" href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noopener noreferrer">Create deployment token ↗</a><details><summary>Which token permissions?</summary><p>Account → Workers Scripts → Edit, Zone → Zone → Read and DNS → Read. Your account must support SQLite Durable Objects for the project team. Optional live domain-price checks need Registrar permissions. Scope the token to your account and intended zones.</p></details><form id="hosting-form"><div class="field"><label for="hosting-account">Cloudflare Account ID</label><input id="hosting-account" value="${esc(x.accountId)}" minlength="32" maxlength="32" pattern="[a-fA-F0-9]{32}" autocomplete="off" required></div><div class="field"><label for="hosting-token">Deployment API token</label><input id="hosting-token" type="password" autocomplete="new-password" minlength="20" maxlength="256" required></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">${x.connected?'Verify & update connection':'Verify & connect Cloudflare'}</button></form></section><section><span class="overline">STEP 3</span><h2>Create your project’s address</h2><p class="setup-notice">${x.connected?'Connection verified '+new Date(x.updated).toLocaleString()+'. '+'Ready to deploy on your root domain.':'Waiting for a verified Cloudflare connection.'}</p><p>Register a new root domain or connect one you own. SOMAS deploys your website and its own AI team together. Cloudflare shows registration and renewal fees before checkout.</p><a class="primary" href="${hostingReturn()}">${id?'Continue project setup':'Back to my projects'} ↗</a></section></div></section></main>`}
const setupLabels={needs_domain:'Choose a separate root domain for your service',awaiting_hosting:'Connect Cloudflare to create your address',queued:'Website address setup queued',awaiting_domain:'Waiting for your new domain to become active',needs_attention:'Setup needs attention',configured:'Address created · deployment follows the approved revision',blocked:'Account action required'};
