function addressForm(x,p){if(x.publication?.address_type==='workers_dev')return '<p>This older service uses a generated subdomain. Create a new project with a root domain to use the independent AI-team release.</p>';const mode=x.publication?(x.publication.address_type==='workers_dev'?'workers_dev':x.intent?.mode||'existing_domain'):x.intent?.mode||p.addressMode||'new_domain',domain=x.intent?.hostname||p.requestedDomain||(x.publication?.address_type!=='workers_dev'?x.publication?.hostname:'')||'';return `<form id="publication-form"><div class="field"><label for="publication-mode">Create a website address</label><select id="publication-mode" ${x.publication?'disabled':''}>${addressOptions(mode)}</select></div><div id="publication-domain-fields" ${mode==='workers_dev'?'hidden':''}><div class="field"><label for="publication-domain">Domain name</label><input id="publication-domain" maxlength="253" value="${esc(domain)}" placeholder="yourproject.com" ${x.publication?'readonly':''} ${mode!=='workers_dev'?'required':''}></div><button class="secondary" type="button" id="domain-check">Check availability & price</button><div id="domain-availability" role="status"></div>${domainCheckout(x.hosting,mode)}</div><p id="generated-address-note" class="modal-note" ${mode==='workers_dev'?'':'hidden'}>New project services require a separate root domain.</p><label class="auto-choice"><input type="checkbox" id="publication-auto" ${x.publication?.auto_publish===0||x.intent?.auto_publish===0?'':'checked'}> Automatically publish approved website revisions</label><button class="primary" type="submit">${x.publication?'Save & publish latest':'Save choice & create address'}</button></form>`}
async function publicationPage(){const epoch=routeEpoch;const [x,loaded]=await Promise.all([api('projects/'+id+'/publication'),api('projects/'+id)]);if(epoch!==routeEpoch)return;publicationData=x;project=loaded.project;const p=x.publication,connected=!!x.link?.connected;$('app').innerHTML=`<main class="dashboard">${appbar(project)}<section class="management-page publication-page"><span class="overline">${esc(project.name)} · SUBNET MANAGER</span><h1>Publish & network.</h1><div class="publication-grid"><section class="publication-panel"><h2>Your independent website</h2><div id="publication-status">${setupSummary(x)}${publicationSummary(p)}</div>${!x.hosting.connected?`<p><a class="primary" href="?screen=hosting&business=${encodeURIComponent(id)}">Create or connect Cloudflare account ↗</a></p>`:''}${addressForm(x,project)}<p><button type="button" class="secondary" id="publication-refresh">Refresh status</button></p><p class="modal-note">Your website and AI team run in your Cloudflare account. Publishing installs your selected provider key as a private Worker secret. Team state, reports and memory stay in this service. Root receives operational reports and sends advice. The team starts paused; open it below and choose Resume. Re-publish after changing the provider key in SOMAS.</p></section><section class="publication-panel"><h2>Root Manager connection</h2><p class="setup-notice">${connected?'Connected to Root Manager':'Disconnected from Root Manager'}</p><p>Root receives team status and publication health. It can send advisory guidance to this Subnet Manager. Your project goal and hosting permissions stay under your control.</p><form id="subnet-link-form"><input type="hidden" id="subnet-next" value="${connected?'disconnect':'connect'}"><button class="secondary" type="submit">${connected?'Disconnect Root Manager':'Connect Root Manager'}</button></form><div id="subnet-message-list">${networkMessages(x.messages)}</div><form id="subnet-report-form"><div class="field"><label for="subnet-report">Report to Root Manager</label><textarea id="subnet-report" minlength="3" maxlength="1200" rows="3" required ${connected?'':'disabled'}></textarea></div><button class="primary" type="submit" ${connected?'':'disabled'}>Send report</button></form></section></div><p id="form-error" class="brief-error" role="alert"></p></section></main>`;
 ticker=setInterval(async()=>{if(epoch!==routeEpoch)return;try{await api('work','POST',{});const next=await api('projects/'+id+'/publication');if(epoch!==routeEpoch)return;publicationData=next;if($('publication-status'))$('publication-status').innerHTML=setupSummary(next)+publicationSummary(next.publication);if($('subnet-message-list'))$('subnet-message-list').innerHTML=networkMessages(next.messages)}catch{markStale()}},6000);
}
async function networkPage(){if(!account.isAdmin){accessDenied();return}const epoch=routeEpoch,x=await api('network');if(epoch!==routeEpoch)return;networkData=x;const selected=params.get('subnet'),chosen=x.subnets.find(s=>s.project_id===selected),messages=chosen?(await api('network/'+encodeURIComponent(selected))).messages:[];if(epoch!==routeEpoch)return;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><span class="overline">ROOT MANAGER</span><h1>Subnet network.</h1><p>Each project has a Subnet Manager. Connected teams send operational status and reports to Root and receive reviewed advisory guidance.</p><a class="secondary" href="?screen=root">Open Root team ↗</a><a class="text-button" href="?screen=network">Refresh network</a><div class="activity-table"><table><thead><tr><th>Subnet Manager</th><th>User / hosting</th><th>Root link</th><th>Team</th><th>Domain</th><th>Publication</th><th>Last website report</th></tr></thead><tbody>${x.subnets.map(s=>`<tr><td><a href="?screen=network&subnet=${encodeURIComponent(s.project_id)}">${esc(s.report.name||s.project_id)}</a></td><td><a href="?screen=users&user=${encodeURIComponent(s.user_id)}">${esc(s.user_name||s.user_id)}</a><br>${s.hosting_connected?'Cloudflare connected':'Cloudflare setup needed'}</td><td>${s.connected?'Connected':'Disconnected'}</td><td>${esc(s.report.status)} · v${s.report.version||0}</td><td>${s.hostname?`<a href="https://${esc(s.hostname)}" target="_blank" rel="noopener noreferrer">${esc(s.hostname)} ↗</a>`:'No domain'}</td><td>${esc(publishLabels[s.publication_status]||setupLabels[s.setup_status]||s.publication_status||'Not configured')}</td><td>${s.last_seen?new Date(s.last_seen).toLocaleString():'Not received'}</td></tr>`).join('')}</tbody></table></div>${!x.subnets.length?'<p>No project subnets yet. New projects connect to Root automatically.</p>':''}${chosen?`<section class="publication-panel"><h2>${esc(chosen.report.name)} · manager messages</h2>${networkMessages(messages)}<form id="root-guidance-form" data-subnet="${esc(selected)}"><div class="field"><label for="root-guidance">Guidance to this Subnet Manager</label><textarea id="root-guidance" minlength="3" maxlength="1200" rows="4" required ${chosen.connected?'':'disabled'}></textarea></div><p class="modal-note">The Subnet Manager considers this advice in its next model task. It cannot change credentials, access rules or hosting settings.</p><button class="primary" type="submit" ${chosen.connected?'':'disabled'}>Send guidance</button></form></section>`:''}<p id="form-error" class="brief-error" role="alert"></p></section></main>`}
async function submitPublishingForm(form,epoch){
 if(form.id==='user-details-form'){await api('admin/users/'+encodeURIComponent(form.dataset.user)+'/details','POST',{label:$('user-label').value.trim(),organization:$('user-organization').value.trim(),notes:$('user-notes').value.trim()});if(epoch!==routeEpoch)return true;await usersPage(form.dataset.user);toast('User information saved.');return true}
 if(form.id==='hosting-form'){await api('hosting','POST',{accountId:$('hosting-account').value.trim(),token:$('hosting-token').value.trim()});if(epoch!==routeEpoch)return true;$('hosting-token').value='';if(id){location.href=hostingReturn();return true}await hostingPage();toast('Cloudflare verified. Saved projects will continue their address setup automatically.');return true}
 if(form.id==='publication-form'){await api('projects/'+id+'/publication','POST',{mode:$('publication-mode').value,hostname:$('publication-domain').value.trim(),autoPublish:$('publication-auto').checked});if(epoch!==routeEpoch)return true;clearInterval(ticker);await publicationPage();return true}
 if(form.id==='subnet-link-form'){await api('projects/'+id+'/subnet','POST',{action:$('subnet-next').value});if(epoch!==routeEpoch)return true;clearInterval(ticker);await publicationPage();return true}
 if(form.id==='subnet-report-form'){await api('projects/'+id+'/subnet','POST',{action:'report',message:$('subnet-report').value.trim()});if(epoch!==routeEpoch)return true;clearInterval(ticker);await publicationPage();return true}
 if(form.id==='root-guidance-form'){await api('network/'+encodeURIComponent(form.dataset.subnet),'POST',{message:$('root-guidance').value.trim()});if(epoch!==routeEpoch)return true;await networkPage();return true}
 return false;
}
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles=[{id:'manager',name:'Manager',color:'#bda4ff',x:50,y:17},{id:'researcher',name:'Researcher',color:'#c3cda0',x:24,y:40},{id:'designer',name:'Designer',color:'#e2bf91',x:79,y:28},{id:'engineer',name:'Engineer',color:'#9bbfd4',x:85,y:60},{id:'customer',name:'Virtual Customer',color:'#a9cba4',x:28,y:81},{id:'learning',name:'Learning Coach',color:'#b7a1d5',x:63,y:81},{id:'operations',name:'Operations',color:'#c9b29a',x:52,y:54}];
let params=new URLSearchParams(location.search),id=params.get('business'),view=params.get('view')==='business'?'business':'team',routeEpoch=0;
