const pendingForms=new WeakSet(),EMAIL_LOGIN_STORAGE='somas.email-login.v1';
let verificationChallenge=null,activityCursor=null,activityRows=[],usersLoad=0,clock=null,lastHomeRender='',workspaceSuspended=false;
const providers=[{id:'groq',name:'Groq',keys:'https://console.groq.com/keys',hint:'gsk_…'},{id:'gemini',name:'Google Gemini',keys:'https://aistudio.google.com/api-keys',hint:'AIza…'},{id:'openai',name:'OpenAI',keys:'https://platform.openai.com/api-keys',hint:'sk-…'},{id:'anthropic',name:'Anthropic Claude',keys:'https://platform.claude.com/settings/keys',hint:'sk-ant-…'},{id:'openrouter',name:'OpenRouter',keys:'https://openrouter.ai/settings/keys',hint:'sk-or-…'}];
const purposes={manager:'Plan · delegate · evaluate',researcher:'Requirements',designer:'Design · accessibility',engineer:'Build · improve',customer:'User experience',operations:'Capability audit',learning:'Team lessons'};
const providerName=()=>providers.find(p=>p.id===(account.provider||'groq'))?.name||'AI';
const stamp=v=>JSON.stringify(v,(key,value)=>key==='serverTime'?undefined:value);
function ageText(start){if(!start)return '—';let n=Math.max(0,Math.floor((Date.now()-Number(start))/1000));const seconds=n%60;n=Math.floor(n/60);const minutes=n%60;n=Math.floor(n/60);const hours=n%24,days=Math.floor(n/24);return (days?days+'d ':'')+(hours||days?hours+'h ':'')+(minutes||hours||days?minutes+'m ':'')+seconds+'s'}
function money(value){return '$'+value.toFixed(value>0&&value<.0001?8:5)}
function costText(usage){if(!usage?.calls)return '—';const known=(usage.estimatedCalls||0)+(usage.reportedCalls||0);if(!known)return 'Unknown';return money((usage.estimatedUsd||0)+(usage.reportedUsd||0))+(usage.unknownCostCalls?' + ?':'')}
function updateSync(p){if(p?.serverTime)document.querySelectorAll?.('[data-synced]').forEach(el=>{el.textContent='Synced '+new Date(p.serverTime).toLocaleTimeString()})}
function markStale(){document.querySelectorAll?.('[data-synced]').forEach(el=>{el.textContent='Connection interrupted · saved state'})}
function updateClocks(){document.querySelectorAll?.('[data-age-start]').forEach(el=>el.textContent=ageText(el.dataset.ageStart));document.querySelectorAll?.('[data-until]').forEach(el=>el.textContent=Math.max(0,Math.ceil((Number(el.dataset.until)-Date.now())/1000))+'s')}
function syncClock(p){clearInterval(clock);clock=null;if(p?.agents?.length){updateClocks();clock=setInterval(updateClocks,1000)}}
function agentLive(p,a){if(a.live)return a.live;if(p.paused)return {state:'paused',label:'Paused'};if(p.status==='setup')return {state:'setup',label:'Connect AI'};const pending=p.reports?.find(r=>r.id===p.pendingReport&&!r.evaluation);if(p.running&&a.id==='manager'&&pending)return {state:'review-queued',label:'Review queued'};return {state:a.state||'resting',label:(a.state||'resting').replace(/^./,c=>c.toUpperCase())}}
function metrics(p){if(!p?.agents?.length)return '';return `<section class="agent-vitals" aria-label="Live agent values"><div class="vitals-heading"><h2>Team vitals</h2><span data-synced>Synced ${p.serverTime?new Date(p.serverTime).toLocaleTimeString():'now'}</span></div><div class="vitals-grid">${p.agents.map(a=>{const live=agentLive(p,a),u=a.usage;return `<button class="vital-card" data-agent="${a.id}"><div class="vital-name"><b>${esc(a.name)}</b><span class="vital-state state-${esc(live.state)}">${esc(live.label)}</span></div><span class="purpose-tag">${esc(a.purpose||purposes[a.id])}</span><dl><div><dt>${a.ageKind==='tracked'?'Tracked':'Age'}</dt><dd data-age-start="${a.ageStart||a.createdAt||''}">${ageText(a.ageStart||a.createdAt)}</dd></div><div><dt>API spend</dt><dd>${costText(u)}</dd></div><div><dt>Learning value</dt><dd class="learning-value">${a.learningValue??a.accepted??0}<small>${a.lastLearning?((a.lastLearning.delta>0?'+':'')+a.lastLearning.delta):''}</small></dd></div></dl><div class="vital-foot">${u?.calls||0} responses · ${((u?.input||0)+(u?.output||0)).toLocaleString()}${u?.missingTokenCalls?' + ?':''} tokens</div></button>`}).join('')}</div><div class="vitals-note">Spend: provider-reported or estimated from your rates · ? = unpriced usage · Learning = accepted lessons${p.unattributedHistoricalCalls?' · '+p.unattributedHistoricalCalls+' older responses lack per-agent usage':''}</div></section>`}

