function safeEmailNext(value){try{if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//'))return '/?screen=dashboard';const u=new URL(value,location.origin);if(u.origin!==location.origin||['/signin-with-chatgpt','/signout-with-chatgpt','/callback'].includes(u.pathname.replace(/\/+$/,''))||u.searchParams.has('welcome')||['login','signup'].includes(u.searchParams.get('screen'))||!u.search)return '/?screen=dashboard';return u.pathname+u.search+u.hash}catch{return '/?screen=dashboard'}}
const signIn=()=> '/?screen=login&next='+encodeURIComponent(safeEmailNext(location.pathname+location.search));
async function api(path,method='GET',body){
 const bounded=path.startsWith('auth/')||['signin-setup','email-setup'].includes(path),controller=bounded?new AbortController():null;
 const timeout=controller?setTimeout(()=>controller.abort(),25000):null;
 try{const r=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,...(controller?{signal:controller.signal}:{})});let x;try{x=await r.json()}catch{throw new Error('The server returned an unreadable response.')}if(!r.ok){const er=new Error(x.error?.message||'Request failed.');Object.assign(er,{status:r.status,code:x.error?.code});throw er}return x}
 catch(er){if(controller?.signal.aborted)throw new Error('The request timed out. Please check your connection and try again.');throw er}finally{if(timeout)clearTimeout(timeout)}
}
function toast(s){clearTimeout(toastTimer);$('toast').textContent=s;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
function modal(content){$('modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="close-modal" id="close-modal" aria-label="Close">×</button>${content}</section></div>`;$('modal-root').querySelector('input,textarea,button:not(.close-modal)')?.focus()}
