function topbar(){return `<header class="topbar"><a class="brand" href="/?screen=dashboard">${brand()}</a><nav class="dashboard-nav" aria-label="Dashboard navigation"><a class="text-button" href="?screen=hosting">Hosting</a><a class="text-button" href="?screen=opinions">Opinions</a>${account.isAdmin?'<a class="text-button" href="?screen=users">User management</a><a class="text-button" href="?screen=root">Root team</a><a class="text-button" href="?screen=network">Subnet network</a>':''}<button class="text-button" id="share-somas">Share</button>${account.signedIn?'<a class="text-button" href="?screen=manager">Become a Manager</a>':''}${account.isAdmin?'<a class="text-button" href="?screen=activity">Activity</a>':''}${account.canConfigureEmail?'<a class="text-button" href="?screen=email-setup">Email settings</a>':''}${account.isOwner?'<a class="text-button" href="?screen=approvals">Approvals</a><a class="text-button" href="?screen=mail">Email delivery</a>':''}<button class="text-button" id="guide">Guide</button><button class="text-button" id="our-idea">Our idea</button>${account.signedIn?`<button type="button" class="text-button" data-open-connect>${account.connected?'Connected ●':'Connect AI ↗'}</button><button class="text-button" id="signout">Sign out</button>`:`<a class="text-button" target="_top" href="${signIn()}">Sign in ↗</a>`}</nav></header>`}
function scene(p,home=false){
 const people=home&&!(p.agents?.length)?roles:roles.filter(r=>p.agents.some(a=>a.id===r.id)),agents=p?.agents||[],pending=p.reports?.find(r=>r.id===p.pendingReport&&!r.evaluation),current=p.tasks?.[0]?.role;
 const positions=Object.fromEntries(people.map(r=>[r.id,p.layout?.[r.id]||(people.length===1?{x:50,y:46}:r)])),manager=positions.manager||roles[0];
 const wires=people.filter(a=>a.id!=='manager').map(a=>{const pos=positions[a.id],live=agentLive(p,agents.find(x=>x.id===a.id)||{}),managerLive=agentLive(p,agents.find(x=>x.id==='manager')||{}),active=p.running&&(pending?.role===a.id||current===a.id),report=pending?.role===a.id;return `<path class="${active?'wire-active':''} ${report?'wire-report':''} ${['quota','retry'].includes(live.state)||['quota','retry'].includes(managerLive.state)?'wire-wait':''}" d="M${manager.x*9} ${manager.y*5.625} Q${manager.x*9} ${pos.y*5.625},${pos.x*9} ${pos.y*5.625}"/>`}).join('');
 return `<div class="office phase-${esc(p.phase||'ready')}" id="${home?'home-office':'team-office'}"><div class="office-floor"></div><div class="office-ambient"></div><div class="plant" aria-hidden="true"></div><svg class="office-wires" viewBox="0 0 900 562.5" preserveAspectRatio="none" aria-hidden="true">${wires}</svg>${people.map(r=>{const a=agents.find(a=>a.id===r.id)||{id:r.id,state:'resting',memoryVersion:0},pos=positions[r.id],live=agentLive(p,a),active=p.running&&['working','evaluating','learning','reporting'].includes(live.state);return `<button class="agent ${active?'active':''} state-${esc(live.state)} ${live.state==='learning'?'training':''}" style="--x:${pos.x};--y:${pos.y};--agent-color:${r.color}" data-agent="${r.id}" aria-label="Inspect ${r.name}: ${esc(live.label)}"><span class="work-label state-${esc(live.state)}">${esc(live.label)}</span><span class="avatar"><i class="eye"></i><i class="eye"></i></span><span class="agent-desk"></span><span class="agent-name">${r.id==='manager'?(p.scope==='service'?'Root Manager':'Subnet Manager'):r.name}</span><span class="agent-policy">LEARNING ${a.learningValue||0}</span></button>`}).join('')}</div>`
}
function taskBoard(p){return `<div class="task-board">${roles.filter(r=>p.agents.some(a=>a.id===r.id)&&r.id!=='manager').map(r=>{const task=p.tasks.find(t=>t.role===r.id),report=p.reports.slice().reverse().find(x=>x.role===r.id),state=task?'Queued':report?.evaluation?'Reviewed':report?'Report sent':'Ready';return `<div><span>${esc(r.name)}</span><small>${esc(state)}</small><p>${esc(clip(task?.task||report?.summary||'Waiting for assignment',95))}</p></div>`}).join('')}</div><div class="activity-trail">${p.history.slice(-4).reverse().map(h=>`<div><time>${new Date(h.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><b>${esc(h.agent)}</b><span>${esc(clip(h.message,125))}</span></div>`).join('')}</div>`}

function mini(p){const s=p?.site||p?.draft;if(!s)return `<div class="mini-website waiting"><span class="building-icon">⌘</span><p>${p?'Waiting for the first real model response.':'Start with a goal.'}</p></div>`;return `<div class="mini-website ${s.theme==='dark'?'mini-dark':''}" style="--edition-accent:${esc(s.accent)}"><div class="mini-nav"><b>${esc(s.name)}</b><span>${p.site?'APPROVED':'DRAFT'}</span></div><div class="mini-hero"><small>${esc(s.tagline)}</small><h3>${esc(s.headline)}</h3><span class="mini-cta">${esc(s.cta)} ↗</span></div><div class="mini-cards">${s.offerings.slice(0,3).map(o=>`<div><i></i><span>${esc(o.title)}</span></div>`).join('')}</div><div class="mini-new-section"><b>${esc(clip(s.about,64))}</b><span>↗</span></div></div>`}
function home(){const homeStamp=stamp({account,projects,rootTeam,serviceSettings});if(homeStamp===lastHomeRender&&$('home-office')){updateSync(rootTeam||projects.find(p=>p.running)||projects[0]);return}lastHomeRender=homeStamp;const latest=projects[0],activity=account.isAdmin&&rootTeam?rootTeam:projects.find(p=>p.running)||latest,available=activity||{agents:[],layout:{}};$('app').innerHTML=`<main class="dashboard">${topbar()}<div class="dashboard-content"><div class="dashboard-heading"><div><span class="overline">YOUR WORKSPACE</span><h1>${esc(serviceSettings.headline)}</h1></div><div class="dashboard-actions"><a class="secondary" href="?screen=opinions">Opinions ↗</a>${account.isAdmin?'<a class="secondary" href="?screen=users">Users ↗</a>':''}<a class="primary" href="?screen=new">New project <span>＋</span></a></div></div>${!account.connected?`<div class="connection-banner"><span>${account.signedIn?'Connect your preferred API provider to start work.':'Sign in to open your own AI workspace.'}</span>${account.signedIn?'<button type="button" class="text-button" data-open-connect>Connect AI ↗</button>':`<a href="${signIn()}" target="_top">Sign in ↗</a>`}</div>`:''}<div class="dashboard-grid"><section class="dashboard-office"><div class="scene-titlebar"><b><i class="live-dot"></i> ${activity?esc(activity.name):'SOMAS team'}</b><span>${activity?.running?'LIVE WORKSPACE':'READY FOR A GOAL'}</span></div>${scene(available,true)}<div class="scene-stage"><span>${activity?.scope==='service'?'ROOT TEAM · SOMAS health & improvement':'PROJECT TEAM · Your goal'}</span><span>${account.connected?esc(providerName().toUpperCase())+' CONNECTED':'NOT CONNECTED'}</span></div></section><aside class="dashboard-overview"><div class="dashboard-stats"><div><strong>${projects.length.toString().padStart(2,'0')}</strong><span>Projects</span></div><div><strong>${projects.reduce((n,p)=>n+p.version,0).toString().padStart(2,'0')}</strong><span>Releases</span></div></div><div class="overview-site"><div class="panel-heading"><h2>${latest?'Latest website':'Your next website'}</h2><span>${latest?'v'+latest.version:'↗'}</span></div>${mini(latest)}<a class="overview-open" href="${latest?url(latest.id,'business'):'?screen=new'}">${latest?esc(latest.name):'Let’s build it'} <span>↗</span></a></div></aside></div>${metrics(activity)}<div class="hierarchy-strip">${account.isAdmin?'<a href="?screen=root"><b>Root Manager</b><span>SOMAS service ↻</span></a>':'<span><b>Root Manager</b> · SOMAS service ↻</span>'}<span>↓ Independent teams</span><a href="?screen=new"><b>Subnet Managers</b><span>Each user’s goal ↻</span></a></div><section class="projects-section"><div class="section-row"><h2>Projects <span>${projects.length}</span></h2><span>Private workspace · cloud saved</span></div><div class="project-grid">${projects.map(p=>`<a class="project-card" href="${url(p.id)}"><span class="project-glyph">◈</span><div><h3>${esc(clip(p.name,30))}</h3><p>${esc(p.status)} · v${p.version}</p></div><span>↗</span></a>`).join('')}<a class="project-card project-add" href="?screen=new"><span>＋</span> New project</a></div></section></div></main>`;syncClock(activity)}
function newPage(){const empty={agents:[{id:'manager',state:'resting',memoryVersion:0}],layout:{}};$('app').innerHTML=`<main class="new-project-page">${topbar()}<div class="new-project-heading"><span class="overline">NEW PROJECT</span><h1>What’s the goal?</h1></div><div class="new-project-grid"><section class="manager-start"><div class="scene-titlebar"><b>Manager</b><span>WAITING FOR YOUR GOAL</span></div>${scene(empty)}<div class="scene-stage"><span>Goal → Team → Website</span><span>REAL MODEL CALLS</span></div></section><section class="project-brief"><span class="brief-icon">✳</span><h2>Your Manager is ready.</h2><form id="project-form"><div class="field"><label for="requirement">Tell me what to build</label><textarea id="requirement" minlength="8" maxlength="1600" rows="4" placeholder="A cozy restaurant with a seasonal menu and a contact form…" required></textarea></div><div class="brief-presets"><button type="button" data-preset="restaurant">Restaurant</button><button type="button" data-preset="store">Store</button><button type="button" data-preset="school">School</button></div><div class="field name-field"><label for="project-name">Project name <span>optional</span></label><input id="project-name" maxlength="70" placeholder="Let the Manager choose"></div><div class="field"><label for="new-address-mode">Website address</label><select id="new-address-mode">${addressOptions('new_domain')}</select></div><div class="field"><label for="new-domain">Root domain <span>choose now or after building</span></label><input id="new-domain" maxlength="253" placeholder="yourbusiness.com" autocomplete="off"><p class="modal-note">Your service and its AI team publish together on your own root domain. SOMAS guides you through Cloudflare setup and domain registration. <a href="?screen=hosting">Open setup guide ↗</a></p></div><label class="auto-choice"><input type="checkbox" id="auto-publish" checked> Publish approved website revisions automatically</label><label class="auto-choice"><input type="checkbox" id="auto-improve" checked> Keep improving until I pause</label><p class="brief-error" id="form-error" role="alert"></p>${account.signedIn?'<button class="primary" type="submit">Start building <span>↗</span></button>':`<a class="primary" target="_top" href="${signIn()}">Sign in to start <span>↗</span></a>`}</form><p class="modal-note">Cloud saved · continuous rounds · quota aware</p></section></div></main>`}
function connectPage(){const provider=account.provider||'groq',cfg=providers.find(p=>p.id===provider)||providers[0],pricing=account.pricing||{mode:'unknown'};$('app').innerHTML=`<main class="new-project-page">${topbar()}<section class="connect-box"><span class="brief-icon">⌘</span><h1>Your key. Your team.</h1><p>Choose the API provider your team uses.</p>${!account.signedIn?`<a class="primary" target="_top" href="${signIn()}">Continue with email <span>↗</span></a>`:`<form id="connect-form"><div class="field"><label for="api-provider">API provider</label><select id="api-provider">${providers.map(p=>`<option value="${p.id}" ${p.id===provider?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="field"><label for="groq-key" id="api-key-label">${cfg.name} API key ${account.connected?'· blank keeps current key':''}</label><input id="groq-key" type="password" autocomplete="off" spellcheck="false" placeholder="${cfg.hint}" ${account.connected?'':'required'}></div><div id="connection-models" ${account.connected?'':'hidden'}><div class="model-grid"><div class="field"><label for="manager-model">Manager model</label><select id="manager-model">${account.models.map(m=>`<option ${account.managerModel===m?'selected':''}>${esc(m)}</option>`).join('')}</select></div><div class="field"><label for="worker-model">Specialist model</label><select id="worker-model">${account.models.map(m=>`<option ${account.workerModel===m?'selected':''}>${esc(m)}</option>`).join('')}</select></div></div></div><div class="billing-box"><div class="field"><label for="billing-mode">API cost tracking</label><select id="billing-mode"><option value="unknown" ${pricing.mode==='unknown'?'selected':''}>Unknown — record tokens only</option><option value="free" ${pricing.mode==='free'?'selected':''}>Free tier — confirmed by me</option><option value="metered" ${pricing.mode==='metered'?'selected':''}>Metered — enter model rates</option></select></div><div class="price-rates" id="price-rates" ${pricing.mode==='metered'?'':'hidden'}><small>USD per 1 million tokens · use your selected models’ rates</small><div class="model-grid">${[['managerInput','Manager input'],['managerOutput','Manager output'],['workerInput','Specialist input'],['workerOutput','Specialist output']].map(([id,label])=>`<div class="field"><label for="rate-${id}">${label}</label><input type="number" min="0" max="100000" step="any" id="rate-${id}" value="${pricing[id]??''}" ${pricing.mode==='metered'?'required':''}></div>`).join('')}</div></div></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">${account.connected?'Save connection':'Connect & verify'} <span>↗</span></button></form><div class="connection-links"><a id="provider-keys-link" href="${cfg.keys}" target="_blank" rel="noopener">Get a ${cfg.name} key ↗</a>${account.connected?'<button id="disconnect">Disconnect key</button>':''}</div><p class="modal-note">Your key stays encrypted on the server. Changing provider requires its own key. Limits and billing depend on your provider account.</p><a class="text-button" href="/?screen=dashboard">← Dashboard</a>`}</section></main>`}
function updatePricingFields(){const metered=$('billing-mode')?.value==='metered';$('price-rates').hidden=!metered;for(const id of ['managerInput','managerOutput','workerInput','workerOutput'])$('rate-'+id).required=metered}
document.addEventListener('change',event=>{if(event.target.id==='publication-mode'){const mode=event.target.value,free=mode==='workers_dev';$('publication-domain-fields').hidden=free;$('publication-domain').required=!free;$('generated-address-note').hidden=!free;$('domain-check').hidden=mode!=='new_domain';if($('paid-domain-help'))$('paid-domain-help').hidden=mode!=='new_domain'}if(event.target.id==='api-provider'){const provider=event.target.value,cfg=providers.find(p=>p.id===provider),same=account.connected&&provider===(account.provider||'groq');$('groq-key').value='';$('groq-key').placeholder=cfg.hint;$('groq-key').required=!same;$('api-key-label').textContent=cfg.name+' API key'+(same?' · blank keeps current key':'');$('connection-models').hidden=!same;$('provider-keys-link').href=cfg.keys;$('provider-keys-link').textContent='Get a '+cfg.name+' key ↗';$('billing-mode').value='unknown';updatePricingFields()}if(event.target.id==='billing-mode')updatePricingFields();if(['manager-model','worker-model'].includes(event.target.id)){$('billing-mode').value='unknown';updatePricingFields()}});
function appbar(p){if(p.scope==='service')return `${topbar()}<div class="root-subnav"><a href="/?screen=dashboard">← Dashboard</a><span>ROOT TEAM · SOMAS SERVICE</span><a href="?screen=network">Subnet network ↗</a><a href="?screen=users">Users ↗</a></div>`;return `<header class="appbar"><a class="brand" href="/?screen=dashboard">${brand()}</a><div class="business-identity"><b>${esc(p.name)}</b></div><nav class="appnav" aria-label="Application pages"><a class="${view==='business'?'active':''}" href="${url(p.id,'business')}">▧ Preview</a><a class="${view==='team'&&params.get('screen')!=='publication'?'active':''}" href="${url(p.id)}">⌘ Agents</a>${!p.readOnly?`<a class="${params.get('screen')==='publication'?'active':''}" href="?screen=publication&business=${encodeURIComponent(p.id)}">Publish & network</a>`:''}</nav><div class="appbar-right"><button type="button" class="text-button" data-open-connect>Settings</button><a class="open-business" href="${p.publication?.url||url(p.id,'business',true)}" target="_blank" rel="noopener">${p.publication?.url?'Open domain':'Open preview'} ↗</a></div></header>`}
function agentDetail(p,agentId){const a=p.agents.find(a=>a.id===agentId);if(!a)return;const live=agentLive(p,a);modal(`<span class="overline">${esc(live.label)}</span><h2 id="modal-title">${esc(a.name)}</h2><div class="agent-inspector-stats"><div><span>Learning value</span><strong>${a.learningValue||0}</strong></div><div><span>API spend</span><strong>${costText(a.usage)}</strong></div><div><span>${a.ageKind==='tracked'?'Tracked':'Age'}</span><strong data-age-start="${a.ageStart||a.createdAt||''}">${ageText(a.ageStart||a.createdAt)}</strong></div></div><span class="purpose-tag">${esc(a.purpose||purposes[a.id])}</span><p class="modal-note">+1 per accepted, evidence-linked lesson. Rejected work adds 0; withdrawn evidence can reduce the value.</p>${a.lastLearning?`<div class="last-learning"><b>Latest change: ${a.lastLearning.delta>0?'+':''}${a.lastLearning.delta}</b><p>${esc(a.lastLearning.lesson)}</p></div>`:''}<div class="memory-list">${a.memory.length?a.memory.slice(-6).reverse().map(m=>`<article><p>${esc(m.lesson)}</p><small>Report ${esc(m.reportId.slice(0,8))}</small></article>`).join(''):'<p>No evaluated lessons yet.</p>'}</div><p class="modal-note">Stored learning, not model-weight training. API spend excludes unknown usage and is not an invoice.${a.ageKind==='tracked'?' Older agents show time since first recorded report.':''}</p>`);updateClocks()}
function team(p){if(p.publication?.team_runtime){$('app').innerHTML=`<main class="dashboard">${appbar(p)}<section class="management-page"><span class="overline">${esc(p.name)} · PROJECT SERVICE</span><h1>Your AI team lives on your domain.</h1><p>Its Manager, specialists, reports and memory run inside your deployed web service.</p>${publicationSummary(p.publication)}<p><a href="?screen=publication&business=${encodeURIComponent(p.id)}">Publish & Root connection ↗</a></p></section></main>`;return}$('app').innerHTML=`<main class="workspace compact-workspace">${appbar(p)}<div class="compact-top"><div><span class="overline">${esc(p.name)}</span><h1>${p.running?(p.scope==='service'?'Improving SOMAS.':'Your team is working.'):p.status==='setup'?'Connect your team.':p.status==='complete'?'Your team is resting.':p.paused?'Your team is paused.':'Your team needs you.'}</h1></div><div class="team-tools">${p.readOnly?`<span class="overline">ADMIN · REVIEW</span>${account.isAdmin?`<button class="secondary" data-admin-project="${esc(p.id)}" data-project-action="${p.running?'pause':'resume'}">${p.running?'Pause':'Resume'} project</button>`:''}`:`<button id="play-pause" class="secondary">${p.running?'Ⅱ Pause':'▶ Resume'}</button>${p.scope!=='service'?'<button id="new-goal" class="secondary">＋ New goal</button>':''}`}</div></div>${p.error?`<div class="runtime-notice"><span>${esc(p.error.message)}</span>${p.error.retry&&p.nextAt>Date.now()?`<span>Retry in <b data-until="${p.nextAt}">${Math.ceil((p.nextAt-Date.now())/1000)}s</b></span>`:''}${p.error.code==='setup_required'||p.error.code==='provider_auth'?'<button type="button" class="text-button" data-open-connect>Connect ↗</button>':''}</div>`:''}<div class="compact-grid"><section class="team-column"><div class="work-scene"><div class="scene-titlebar"><b><i class="live-dot"></i> ${esc(p.status==='queued'&&p.nextAt>Date.now()?(p.error?.code==='provider_quota'?'Quota · retry '+new Date(p.nextAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'Next task queued'):p.status)}</b><span>${p.agents.length} AGENTS</span></div>${scene(p)}<div class="scene-stage"><span>${p.phase==='review'?(p.error?.code==='provider_quota'?'Report saved · Manager waiting for quota':p.busy?'Manager reviews the report':'Report saved · Manager review queued'):p.phase==='plan'?'Manager organizes the team':p.phase==='settle'?'Recording evaluated lessons':p.tasks[0]?esc(clip(p.tasks[0].task,65)):'Work complete'}</span><span>ROUND ${p.cycle+1} ${p.autoImprove?'↻ CONTINUOUS':'· SINGLE'}</span></div></div>${metrics(p)}${taskBoard(p)}<div class="team-caption"><span>${p.calls||0} real model responses · ${p.tokens||0} tokens</span>${p.readOnly?'':'<button id="reset-layout">Reset layout ↺</button>'}</div><div class="review-toolbar"><button id="reports">Reports <b>${p.reports.length}</b></button><button id="revisions">Revisions <b>${p.version}</b></button>${p.scope==='service'?'<a class="secondary" href="?screen=opinions">Opinions ↗</a>':p.readOnly?'':'<button id="inquiries">Inquiries ↗</button>'}</div><p class="run-note">Fast work while SOMAS is open · hourly background rounds · pauses at quota limits.</p></section><aside class="live-preview-panel"><div class="panel-heading"><h2><i class="live-dot"></i> ${p.scope==='service'?'Service improvements':'Your website'}</h2><span class="version-pill">${p.version?'v'+p.version:p.draft?'DRAFT':'WAITING'}</span></div><div class="live-browser-bar"><i></i><i></i><i></i><span>${p.scope==='service'?'Applied service settings':p.site?'Validated release':'Awaiting Manager approval'}</span></div><div class="live-preview-frame" data-revision="${p.version}">${p.scope==='service'?servicePanel(p):mini(p)}</div><div class="release-summary"><span>${p.releases.length?esc(clip(p.releases.at(-1).summary,60)):'A real response is required.'}</span></div>${p.scope==='service'?'<a class="primary" href="?screen=opinions">Read opinions <span>↗</span></a>':`<a class="primary" href="${url(p.id,'business')}">Open Business <span>↗</span></a>`}<div class="single-activity"><b>${esc(p.history.at(-1)?.agent||'Manager')}</b><span>${esc(clip(p.history.at(-1)?.message,85))}</span></div></aside></div></main>`;syncClock(p)}
function business(p){const s=p.site,savedDraft=$('chat-message')?.value||'',savedName=$('chat-name')?.value||'';$('app').innerHTML=`<div class="business-page ${s?.theme==='dark'?'business-dark':''} real-business ${s?.layout==='centered'?'site-centered':''}" style="--biz-accent:${esc(s?.accent||'#34563d')};--biz-soft:${esc(s?.accent||'#dce3c9')}22">${appbar(p)}<div class="business-live-bar"><span><i class="live-dot"></i> ${p.running?'Team improving':'Team resting'} · v${p.version}</span><a href="${url(p.id)}">View agents ↗</a><button id="play-pause">${p.running?'Ⅱ Pause':'▶ Resume'}</button></div>${!s?`<section class="business-empty"><div><span class="building-icon" style="margin:auto">⌘</span><h1>No release yet.</h1><p>${p.draft?'The Manager is reviewing the first website.':'Connect your team and start building.'}</p><a class="biz-button" href="${url(p.id)}">Watch the team ↗</a></div></section>`:`<header class="business-header"><a class="business-logo" href="#">${esc(s.name)}</a><nav aria-label="Business navigation"><a href="#offerings">Explore</a><a href="#about">About</a><button class="biz-button" id="contact">${esc(s.cta)} ↗</button></nav></header><main class="business-wrap">${p.kind==='chatroom'?chatPanel():''}<section class="business-hero"><div><span class="overline">${esc(s.tagline)}</span><h1>${esc(s.headline)}</h1><p>${esc(s.description)}</p><button class="biz-button" id="contact-hero">${esc(s.cta)} ↗</button></div><div class="biz-art" aria-label="Abstract business illustration"><div class="art-orbit"></div><div class="art-plate"></div><span class="art-label">${esc(s.name)}</span><span class="art-sticker">${esc(s.tagline.split(' ').slice(0,3).join(' '))}</span></div></section><section class="biz-section" id="offerings"><div class="biz-section-heading"><h2>Explore our offering.</h2><span>Built around your goal</span></div><div class="biz-cards">${s.offerings.map((o,i)=>`<article class="biz-card"><div class="biz-card-art"><span class="object" aria-hidden="true">${['◈','♧','◎','✳','⌕','◌'][i]}</span></div><div class="biz-card-text"><div><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p></div><button data-offering="${i}" aria-label="Ask about ${esc(o.title)}">↗</button></div></article>`).join('')}</div></section><section class="biz-upgrade" id="about"><div><div class="upgrade-label">ABOUT ${esc(s.name)}</div><h2>${esc(s.tagline)}</h2><p>${esc(s.about)}</p></div><button class="biz-button" id="contact-about">${esc(s.cta)} ↗</button></section>${s.faq.length?`<section class="biz-faq"><h2>Good to know.</h2><div>${s.faq.map(q=>`<details><summary>${esc(q.question)}</summary><p>${esc(q.answer)}</p></details>`).join('')}</div></section>`:''}<footer class="business-footer"><span>${esc(s.name)} · Built by SOMAS</span><span>Validated release v${p.version}</span></footer></main>`}</div>`;if(p.kind==='chatroom'){if($('chat-message'))$('chat-message').value=savedDraft;if($('chat-name'))$('chat-name').value=savedName;renderMessages();loadMessages()}}
function chatPanel(){return `<section class="chat-panel"><div class="chat-heading"><div><span class="overline">PRIVATE WORKSPACE</span><h2>General <span>●</span></h2></div><small>Saved messages · refreshes every 3s</small></div><div id="chat-messages" class="chat-messages" role="log" aria-label="General messages"></div><form id="chat-form"><input id="chat-name" aria-label="Display name" placeholder="Your name" maxlength="40" required><input id="chat-message" aria-label="Message" placeholder="Write a message…" maxlength="1500" required><button class="biz-button" type="submit">Send ↗</button><p id="chat-error" role="status"></p></form><small>This room is private to your workspace. Public rooms and file sharing are not enabled.</small></section>`}
function renderMessages(){const node=$('chat-messages');if(!node)return;node.innerHTML=chatMessages.length?chatMessages.map(m=>`<article><div><b>${esc(m.name)}</b><time>${new Date(m.created).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div><p>${esc(m.message)}</p></article>`).join(''):'<p class="chat-empty">Start the conversation.</p>';node.scrollTop=node.scrollHeight}
async function loadMessages(){if(!id||view!=='business'||project?.kind!=='chatroom'||chatLoading)return;const epoch=routeEpoch,projectId=id;chatLoading=true;lastChatPoll=Date.now();try{const x=await api('projects/'+projectId+'/messages');if(epoch!==routeEpoch||id!==projectId)return;const changed=JSON.stringify(x.messages)!==JSON.stringify(chatMessages);chatMessages=x.messages;if(changed||!$('chat-messages')?.children.length)renderMessages()}catch(er){if($('chat-error'))$('chat-error').textContent=er.message}finally{chatLoading=false}}

function servicePanel(p){return `<div class="service-panel"><span class="overline">LIVE SETTINGS · v${p.version}</span><h3>${esc(p.serviceConfig.headline)}</h3><p>${esc(p.serviceConfig.guide)}</p><dl><dt>Call spacing</dt><dd>${p.serviceConfig.callIntervalMs/1000}s</dd><dt>Scope</dt><dd>SOMAS service</dd><dt>Last diagnostic</dt><dd>${p.evidence?new Date(p.evidence.at).toLocaleTimeString():'Pending'}</dd></dl><h4>Observed problems</h4>${p.issues?.length?p.issues.map(i=>`<article><b>${esc(i.title)}</b><small>${i.status==='needs_code'?'Needs code tooling':'Observed · not marked fixed'}</small><p>${esc(clip(i.evidence,150))}</p></article>`).join(''):'<p>No diagnostic findings yet.</p>'}<small>Can apply dashboard copy, Guide text and call spacing. Source-code fixes need an execution/deployment toolchain.</small></div>`}
function accessDenied(){$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><h1>Administrator access required.</h1><a href="/?screen=dashboard">← Dashboard</a></section></main>`}
async function usersPage(selected=params.get('user')){const epoch=routeEpoch,request=++usersLoad;if(!account.isAdmin){accessDenied();return}try{const list=await api('admin/users');if(epoch!==routeEpoch||request!==usersLoad)return;const chosen=list.users.find(u=>u.id===selected)||list.users[0]||null;let matching=[];if(chosen){const x=await api('admin/users/'+encodeURIComponent(chosen.id)+'/projects');if(epoch!==routeEpoch||request!==usersLoad)return;matching=x.projects}userRows=list.users;selectedUser=chosen;userProjects=matching;history.replaceState?.({},'',location.pathname+'?screen=users'+(selectedUser?'&user='+encodeURIComponent(selectedUser.id):''));params=new URLSearchParams(location.search);$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><a class="text-button" href="/?screen=dashboard">← Dashboard</a><div class="section-row"><div><span class="overline">ADMINISTRATION</span><h1>User management<span>.</span></h1></div><span>${userRows.length} users · ${userRows.reduce((n,u)=>n+u.projects,0)} projects</span></div><div class="users-layout"><aside class="users-list">${userRows.map(u=>`<button class="user-row ${selectedUser?.id===u.id?'selected':''}" data-user="${esc(u.id)}"><span class="user-avatar">${esc(u.name.slice(0,1).toUpperCase())}</span><span><b>${esc(u.name)}</b><small>${esc(u.role)} · ${u.projects} projects</small></span><span>↗</span></button>`).join('')||'<p>No users yet.</p>'}</aside><section class="user-projects">${selectedUser?`<div class="selected-profile"><h2>${esc(selectedUser.name)}</h2><p>${esc(selectedUser.email||'Email not supplied by sign-in')}</p><span>${selectedUser.connected?'AI connected':'AI not connected'} · ${selectedUser.projects} projects · ${esc(selectedUser.status||'active')} · ${selectedUser.email_verified_at?'Email verified':'Email unverified'}</span></div>${selectedUser?`<div class="user-actions"><a class="secondary" href="?screen=activity&user=${encodeURIComponent(selectedUser.id)}">View activity</a>${selectedUser.role!=='Owner'&&selectedUser.id!==account.user?.id?`<button class="secondary" data-user-action="${selectedUser.status==='suspended'?'activate':'suspend'}" data-target-user="${esc(selectedUser.id)}">${selectedUser.status==='suspended'?'Reactivate':'Suspend'} user</button>${account.isOwner&&selectedUser.role==='Manager'?`<button class="secondary" data-user-action="revoke-manager" data-target-user="${esc(selectedUser.id)}">Revoke Manager</button>`:''}`:''}</div>`:''}${userManagementInfo(selectedUser)}<div class="project-grid">${userProjects.map(p=>`<a class="project-card" href="${url(p.id)}"><span class="project-glyph">◈</span><div><h3>${esc(p.name)}</h3><p>${esc(p.status)} · v${p.version} · Round ${p.cycle+1}</p><small>${esc(clip(p.requirement,110))}</small></div><span>↗</span></a><button class="secondary" data-admin-project="${esc(p.id)}" data-project-action="${p.running?'pause':'resume'}">${p.running?'Pause':'Resume'} project</button>`).join('')||'<p class="empty-projects">This user has no projects yet.</p>'}</div>`:'Select a user.'}</section></div></section></main>`}catch(er){toast(er.message)}}
async function opinionsPage(){if(!account.signedIn){$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page opinions-page"><span class="overline">HELP SOMAS IMPROVE</span><h1>Opinions<span>.</span></h1><p>Sign in to share an idea or report a problem.</p><a class="primary" target="_top" href="${signIn()}">Continue with email ↗</a></section></main>`;return}const epoch=routeEpoch;try{opinionRows=(await api('opinions')).opinions;if(epoch!==routeEpoch)return;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page opinions-page"><a class="text-button" href="/?screen=dashboard">← Dashboard</a><span class="overline">HELP SOMAS IMPROVE</span><h1>Opinions<span>.</span></h1><p>The root team reviews your feedback. Save your opinion, then send a copy from your email to the owner.</p><p class="modal-note">Managers can review account actions, project activity, and submitted feedback. API keys and verification codes are excluded from the activity log.</p><form id="opinion-form"><label for="opinion-message">What should SOMAS improve?</label><textarea id="opinion-message" minlength="3" maxlength="2000" rows="4" required placeholder="A problem you noticed, or a better way to work…"></textarea><p id="form-error" class="brief-error" role="alert"></p><button type="submit" class="primary">Send opinion <span>↗</span></button></form><div class="opinion-list">${opinionRows.map(o=>`<article><div><b>${esc(o.name||'Your opinion')}</b><time>${new Date(o.created).toLocaleDateString()}</time></div><p>${esc(o.message)}</p><small>Available to Root Manager · not a promise that a fix is complete</small></article>`).join('')||'<p>No opinions yet.</p>'}</div></section></main>`}catch(er){toast(er.message)}}

function reportsModal(){modal(`<span class="overline">TASK EVIDENCE</span><h2 id="modal-title">Team reports</h2><div class="report-list">${project.reports.length?project.reports.slice().reverse().map(r=>`<details><summary><b>${esc(roles.find(a=>a.id===r.role)?.name)}</b><span>${r.runtimeRejected?'Unsupported claim':r.evaluation?(r.evaluation.accepted?'✓ Accepted':'↺ Changes requested'):'Awaiting review'}</span></summary><p>${esc(r.summary)}</p><p>${esc(r.findings)}</p>${r.evaluation?`<div class="report-review"><b>Manager · ${r.evaluation.score}% assessed quality</b><p>${esc(r.evaluation.reason)}</p><small>Manager lesson</small><p>${esc(r.evaluation.managerLesson)}</p></div>`:''}<small>${esc(r.model)} · ${r.usage.input+r.usage.output} tokens · response ${esc(r.requestId||'unavailable')}</small></details>`).join(''):'<p>No reports yet. Connect a model and start work.</p>'}</div>`)}
function revisionsModal(){modal(`<span class="overline">VALIDATED RELEASES</span><h2 id="modal-title">Website history</h2><div class="report-list">${project.releases.slice().reverse().map(r=>`<article><b>v${r.version}</b><p>${esc(r.summary)}</p><small>${new Date(r.at).toLocaleString()}</small>${r.version!==project.version&&!project.readOnly?`<button class="secondary" data-rollback="${r.version}">Restore v${r.version}</button>`:''}</article>`).join('')||'<p>No approved releases yet.</p>'}</div>`)}
function contactModal(item=''){modal(`<span class="overline">${esc(project.site.name)}</span><h2 id="modal-title">${esc(project.site.cta)}</h2><form id="contact-form"><div class="field"><label for="contact-name">Name</label><input id="contact-name" autocomplete="name" maxlength="100" required></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" type="email" autocomplete="email" maxlength="200" required></div><div class="field"><label for="contact-message">Message</label><textarea id="contact-message" minlength="3" maxlength="1500" required>${esc(item?'I’m interested in '+item+'.':'')}</textarea></div><p class="brief-error" id="form-error" role="alert"></p><button class="primary">Save inquiry <span>↗</span></button></form><p class="modal-note">Saved to this project’s inbox. Email delivery and payments are not connected.</p>`)}
function renderProject(){updateSync(project);if(!project||params.get('screen')==='connect'||params.get('screen')==='login')return;const renderStamp=stamp(view==='business'?{site:project.site,version:project.version,running:project.running,status:project.status==='setup'?'setup':null}:project);if(renderStamp===lastRender||drag)return;lastRender=renderStamp;document.title=project.name+' — SOMAS';if(view==='business'&&project.scope!=='service')business(project);else team(project)}
async function pump(){if(Date.now()-lastChatPoll>3000)loadMessages();if(!project||polling||drag||(params.get('screen')&&params.get('screen')!=='root'))return;const epoch=routeEpoch;polling=true;try{const loaded=(await api('projects/'+id)).project;if(epoch!==routeEpoch)return;project=loaded;renderProject();if(!project.readOnly&&project.running&&!project.busy&&!stepping&&Date.now()>=project.nextAt){stepping=true;api('projects/'+id+'/step','POST',{}).then(x=>{if(epoch!==routeEpoch)return;project=x.project;renderProject()}).catch(er=>{if(er.status!==409)toast(er.message)}).finally(()=>{if(epoch===routeEpoch)stepping=false})}}catch(er){markStale();if(er.status===401){clearInterval(ticker);toast('Your session ended. Sign in again.')}else toast(er.message)}finally{if(epoch===routeEpoch)polling=false}}
async function control(action,extra={}){const x=await api('projects/'+id+'/control','POST',{action,...extra});project=x.project;lastRender='';renderProject();pump()}
function readRoute(){params=new URLSearchParams(location.search);id=params.get('business');view=params.get('view')==='business'?'business':'team'}
function openConnection(){if(account.status==='suspended'){suspendedPage();return}if(account.verificationRequired&&!(account.accountVerified??account.emailVerified)){verificationPage();return}if(params.get('screen')==='connect'&&$('groq-key')){$('groq-key').focus();return}clearInterval(ticker);clearInterval(clock);clock=null;ticker=null;lastHomeRender='';routeEpoch++;project=null;polling=false;stepping=false;lastRender='';history.pushState({},'',location.pathname+'?screen=connect');readRoute();closeModal();connectPage();$('groq-key')?.focus()}
function refreshRoute(){if(!$('workspace-root'))return;const next=new URLSearchParams(location.search);if(!workspaceSuspended&&next.toString()===params.toString())return;workspaceSuspended=false;clearInterval(ticker);clearInterval(clock);clock=null;ticker=null;lastHomeRender='';routeEpoch++;project=null;polling=false;stepping=false;lastRender='';chatMessages=[];lastChatPoll=0;readRoute();boot()}
window.addEventListener('somas:suspend',()=>{workspaceSuspended=true;clearInterval(ticker);clearInterval(clock);ticker=null;clock=null;routeEpoch++;project=null;polling=false;stepping=false;lastRender='';lastHomeRender=''});
window.addEventListener('popstate',refreshRoute);window.addEventListener('somas:navigate',refreshRoute);
async function boot(){if(!$('workspace-root'))return;const epoch=routeEpoch;if(params.get('screen')==='signin-setup'){location.href='/?screen=email-setup';return}if(['login','signup'].includes(params.get('screen'))){emailLoginPage();return}try{const me=await api(['signin-setup','email-setup'].includes(params.get('screen'))?'me?context=owner-setup':'me');if(epoch!==routeEpoch)return;account=me;if(account.status==='suspended'){suspendedPage();return}if(params.get('screen')==='email-setup'){await emailSetupPage();return}if(params.get('screen')==='verify'&&!account.emailVerified){verificationPage();return}if(account.verificationRequired&&!(account.accountVerified??account.emailVerified)){verificationChallenge=account.verification||verificationChallenge;verificationPage();return}recordPageActivity();const list=await api('projects');if(epoch!==routeEpoch)return;projects=list.projects;try{serviceSettings=(await api('service')).config||serviceSettings;if(account.isAdmin)rootTeam=(await api('root')).project}catch{}if(account.connected)api('work','POST',{}).catch(()=>{})}catch(er){if(er.status===401&&['signin-setup','email-setup'].includes(params.get('screen'))){ownerSetupGate();return}if(er.status===401){location.href=signIn();return}if(er.status!==401){$('app').innerHTML=`<main class="empty-state"><div><h1>Workspace unavailable.</h1><p>${esc(er.message)}</p><button class="primary" onclick="location.reload()">Retry ↻</button></div></main>`;return}}if(epoch!==routeEpoch)return;if(params.get('screen')==='hosting'){await publishingRoute(hostingPage);return}if(params.get('screen')==='network'){await publishingRoute(networkPage);return}if(params.get('screen')==='publication'&&id){await publishingRoute(publicationPage);return}if(params.get('screen')==='manager'){await managerPage();return}if(params.get('screen')==='approvals'){await approvalsPage();return}if(params.get('screen')==='activity'){await activityPage();return}if(params.get('screen')==='mail'){await mailPage();return}if(params.get('screen')==='users'){await usersPage();return}if(params.get('screen')==='opinions'){await opinionsPage();return}if(params.get('screen')==='root'){if(!account.isAdmin){accessDenied();return}project=rootTeam;id=project.id;view='team';renderProject();ticker=setInterval(pump,1500);pump();return}if(id){try{const loaded=(await api('projects/'+id)).project;if(epoch!==routeEpoch)return;project=loaded;renderProject();ticker=setInterval(pump,1500);pump()}catch(er){$('app').innerHTML=`<main class="empty-state"><div><h1>${er.status===401?'Open your workspace.':'Project unavailable.'}</h1><p>${esc(er.message)}</p><a class="primary" target="_top" href="${er.status===401?signIn():'/?screen=dashboard'}">${er.status===401?'Sign in':'Dashboard'} ↗</a></div></main>`}return}if(params.get('screen')==='new')newPage();else if(params.get('screen')==='connect'||params.get('screen')==='login')connectPage();else{home();if(account.signedIn)ticker=setInterval(async()=>{try{const list=await api('projects');if(epoch!==routeEpoch||(params.get('screen')&&params.get('screen')!=='dashboard')||id)return;projects=list.projects;if(account.isAdmin){rootTeam=(await api('root')).project;serviceSettings=rootTeam?.serviceConfig||serviceSettings;}if(epoch!==routeEpoch||(params.get('screen')&&params.get('screen')!=='dashboard')||id)return;home();if(account.connected&&!stepping){stepping=true;api('work','POST',{}).catch(()=>{}).finally(()=>{stepping=false})}}catch{markStale()}},2000)}}
document.addEventListener('click',async event=>{if(!$('workspace-root'))return;const b=event.target.closest('button,a');if(!b)return;try{if(b.id==='open-local-team'){b.disabled=true;try{const x=await api('projects/'+id+'/team-access','POST',{});location.href=x.url}finally{b.disabled=false}return}if(b.id==='domain-check'){b.disabled=true;try{const result=await api('hosting/domain-check','POST',{hostname:$('publication-domain').value.trim()});$('domain-availability').innerHTML=`<p><b>${esc(result.hostname)}</b>: ${result.registrable?'Available now':'Not available through the Registrar API'}${result.reason?' · '+esc(result.reason):''}</p>${result.pricing?`<p>Registration: ${esc(result.pricing.currency)} ${esc(result.pricing.registration)} · renewal: ${esc(result.pricing.currency)} ${esc(result.pricing.renewal)}</p>`:''}<p class="modal-note">Availability and prices can change. Review the final price and approve checkout in Cloudflare.</p>`}catch(er){$('domain-availability').textContent=er.message+' You can also search and review the price in Cloudflare.'}finally{b.disabled=false}return}if(b.id==='publication-refresh'){b.disabled=true;try{await api('work','POST',{});const x=await api('projects/'+id+'/publication');publicationData=x;$('publication-status').innerHTML=setupSummary(x)+publicationSummary(x.publication);$('subnet-message-list').innerHTML=networkMessages(x.messages)}finally{b.disabled=false}return}if(b.id==='owner-setup-signout'){await api('auth/email/logout','POST',{});location.reload();return}if(b.id==='change-login-email'){emailAttempt++;emailLoginChallenge=null;saveEmailLogin();emailLoginPage();return}if(b.id==='resend-login-code'){b.disabled=true;try{await requestEmailCode(emailLoginAddress)}finally{b.disabled=false}return}if(b.id==='signout'){await api('auth/email/logout','POST',{});location.href='/signout-with-chatgpt?return_to='+encodeURIComponent('/?screen=login');return}if(b.id==='share-somas'){await shareModal();return}if(b.id==='send-verification'){const sent=await api('auth/send-verification'+(account.canConfigureEmail?'?context=owner-setup':''),'POST',{});if(sent.verified){await boot();return}verificationChallenge=sent;verificationPage();toast(sent.delivery==='accepted'?'Verification email accepted for delivery.':'Verification email queued for retry.');return}if(b.dataset.approval){approvalModal(b.dataset.approval);return}if(b.dataset.reject){await api('admin/manager-requests/'+encodeURIComponent(b.dataset.reject),'POST',{action:'reject'});await approvalsPage();return}if(b.dataset.userAction){modal(`<h2 id="modal-title">Confirm user access change</h2><p>${esc(b.dataset.userAction)} access for ${esc(b.dataset.targetUser)}?</p><button class="primary" data-confirm-user="${esc(b.dataset.targetUser)}" data-confirm-action="${esc(b.dataset.userAction)}">Confirm change</button>`);return}if(b.dataset.confirmUser){await api('admin/users/'+encodeURIComponent(b.dataset.confirmUser)+'/access','POST',{action:b.dataset.confirmAction});closeModal();await usersPage(b.dataset.confirmUser);return}if(b.dataset.adminProject){await api('admin/projects/'+encodeURIComponent(b.dataset.adminProject)+'/control','POST',{action:b.dataset.projectAction});if(project?.id===b.dataset.adminProject){project=(await api('projects/'+project.id)).project;lastRender='';renderProject()}else await usersPage();return}if(b.id==='activity-refresh'){await activityPage();return}if(b.id==='activity-more'){await activityPage(true);return}if(b.id==='retry-mail'){await api('admin/mail','POST',{});await mailPage();return}if(b.id==='copy-share'){await copyShare();return}if(b.dataset.shareChannel){if(['instagram','youtube'].includes(b.dataset.shareChannel))await copyShare();api('activity','POST',{screen:'share',platform:b.dataset.shareChannel}).catch(()=>{});return}if(b.hasAttribute('data-open-connect')){event.preventDefault();openConnection();return}if(b.id==='close-modal'){closeModal();return}if(b.id==='guide')modal(`<span class="overline">GUIDE</span><h2 id="modal-title">Goal. Team. Business.</h2><div class="short-guide"><div><b>01</b><span>Select a provider and connect your key.</span></div><div><b>02</b><span>${esc(serviceSettings.guide)}</span></div><div><b>03</b><span>Watch reports become reviewed releases.</span></div></div><a class="primary" href="?screen=new">New project ＋</a><p class="modal-note">Continuous rounds while open, with hourly background work. Quotas queue tasks automatically.</p>`);if(b.dataset.user){await usersPage(b.dataset.user);return}if(b.id==='our-idea')modal(`<span class="overline">OUR IDEA</span><h2 id="modal-title">Two levels.<br>One continuous loop.</h2><div class="idea-loop"><strong>Root Manager → SOMAS</strong><span>↻</span><strong>Project Manager → Your goal</strong><span>↻</span><span>Find · assign · report · review · improve</span></div><p class="modal-note">Each agent has its own persistent memory. The Manager evaluates reports before lessons and website revisions are saved. Model weights are unchanged.</p>`);if(b.dataset.preset){const samples={restaurant:'Build a cozy restaurant website with a seasonal menu, our story and an inquiry form. Do not invent an address or prices.',store:'Build a website showcasing handmade home goods, with product categories and a contact form. No checkout or payments yet.',school:'Build a school website explaining learning programs, our approach and an inquiry form. Do not invent accreditations.'};$('requirement').value=samples[b.dataset.preset];$('requirement').focus()}if(b.dataset.agent&&!dragged){if(project)agentDetail(project,b.dataset.agent);else if(rootTeam?.agents.some(a=>a.id===b.dataset.agent))agentDetail(rootTeam,b.dataset.agent);else if(projects.find(p=>p.agents.some(a=>a.id===b.dataset.agent)))agentDetail(projects.find(p=>p.agents.some(a=>a.id===b.dataset.agent)),b.dataset.agent);else{const a=roles.find(r=>r.id===b.dataset.agent);toast(a.name+' · '+(b.dataset.agent==='researcher'?'Manager support':'Ready for a project'))}}if(b.id==='play-pause')await control(project.running?'pause':'resume');if(b.id==='new-goal')modal(`<span class="overline">NEW GOAL</span><h2 id="modal-title">What should improve?</h2><form id="goal-form"><div class="field"><label for="new-goal-text">Tell your Manager</label><textarea id="new-goal-text" minlength="8" maxlength="1600" required placeholder="Make the website dark and explain our services more clearly…"></textarea></div><p class="brief-error" id="form-error" role="alert"></p><button class="primary">Send goal ↗</button></form>`);if(b.id==='reports')reportsModal();if(b.id==='revisions')revisionsModal();if(b.id==='reset-layout'){project=(await api('projects/'+id+'/layout','POST',{reset:true})).project;lastRender='';renderProject()}if(b.dataset.rollback){project=(await api('projects/'+id+'/rollback','POST',{version:Number(b.dataset.rollback)})).project;closeModal();lastRender='';renderProject();toast('Revision restored.')}if(b.id==='disconnect'){await api('settings','DELETE');account=await api('me');connectPage();toast('Key disconnected.')}if(['contact','contact-hero','contact-about'].includes(b.id)){if(project.kind==='chatroom'){$('chat-name')?.focus();$('chat-messages')?.scrollIntoView({behavior:'smooth',block:'center'})}else contactModal()}if(b.dataset.offering!==undefined)contactModal(project.site.offerings[Number(b.dataset.offering)].title);if(b.id==='inquiries'){const x=await api('projects/'+id+'/inquiries');modal(`<span class="overline">PROJECT INBOX</span><h2 id="modal-title">Inquiries</h2><div class="report-list">${x.inquiries.length?x.inquiries.map(i=>`<article><b>${esc(i.name)}</b><small>${esc(i.email)}</small><p>${esc(i.message)}</p></article>`).join(''):'<p>No inquiries yet.</p>'}</div>`)}}catch(er){toast(er.message)}});
document.addEventListener('click',event=>{if(event.target.id==='modal-backdrop')closeModal()});
document.addEventListener('submit',async event=>{if(!$('workspace-root'))return;event.preventDefault();const form=event.target,b=form.querySelector('button[type="submit"],button.primary'),submitEpoch=routeEpoch;if(pendingForms.has(form))return;pendingForms.add(form);if(b)b.disabled=true;try{if(['hosting-form','publication-form','subnet-link-form','subnet-report-form','root-guidance-form','user-details-form'].includes(form.id)){await submitPublishingForm(form,submitEpoch);return}if(form.id==='password-login'||form.id==='password-signup'){await submitPasswordForm(form);return}if(form.id==='email-login-start'){$('form-error').textContent='';const address=$('signin-email').value.trim();if(await requestEmailCode(address))$('signin-code')?.focus();return}if(form.id==='email-login-verify'){const result=await api('auth/email/verify','POST',{id:emailLoginChallenge?.id,email:emailLoginAddress,code:$('signin-code').value.trim(),next:safeEmailNext(params.get('next'))});if(submitEpoch!==routeEpoch)return;emailLoginChallenge=null;saveEmailLogin();location.href=result.next;return}if(form.id==='gmail-app-form'){await api('email-setup/google','POST',{clientId:$('oauth-client-id').value.trim(),clientSecret:$('oauth-client-secret').value.trim()});if(submitEpoch!==routeEpoch)return;$('oauth-client-secret').value='';await emailSetupPage();toast('Google app saved. Click Connect Gmail to authorize sending.');return}if(form.id==='email-setup-form'){await api('email-setup','POST',{key:$('sender-key').value.trim(),from:$('sender-from').value.trim()});if(submitEpoch!==routeEpoch)return;$('sender-key').value='';location.href='/?screen=dashboard';return}if(form.id==='verify-email-form'){await api('auth/verify-email'+(account.canConfigureEmail?'?context=owner-setup':''),'POST',{id:verificationChallenge?.id,code:$('verification-code').value.trim()});verificationChallenge=null;await boot();return}if(form.id==='manager-request-form'){await api('manager-request','POST',{reason:$('manager-reason').value.trim()});await managerPage();return}if(form.id==='manager-approval-form'){await api('admin/manager-requests/'+encodeURIComponent(form.dataset.request),'POST',{action:'approve',code:$('approval-code').value.trim()});closeModal();await approvalsPage();return}if(form.id==='opinion-form'){const submitEpoch=routeEpoch;const result=await api('opinions','POST',{message:$('opinion-message').value.trim()});if(submitEpoch!==routeEpoch)return;await opinionsPage();modal(`<h2 id="modal-title">Opinion saved.</h2><p class="modal-note">Send a copy from <b>${esc(result.emailDraft.senderEmail)}</b> to <b>${esc(result.emailDraft.recipient)}</b>.</p><a class="primary" href="${esc(result.emailDraft.url)}">Send from my email ↗</a><p class="modal-note">Opens a draft in your email app. Select your signup mailbox and click Send there. Opening the draft does not send it; SOMAS cannot confirm delivery.</p><p class="modal-note">${result.notification==='accepted'?'A separate SOMAS notification was accepted by the email provider.':'A separate SOMAS notification is queued until email delivery is available.'}</p><button class="secondary" id="close-modal">Done</button>`)}if(form.id==='chat-form'){await api('projects/'+id+'/messages','POST',{name:$('chat-name').value.trim(),message:$('chat-message').value.trim()});$('chat-message').value='';await loadMessages();$('chat-message').focus()}if(form.id==='project-form'){const x=await api('projects','POST',{requirement:$('requirement').value.trim(),name:$('project-name').value.trim(),autoImprove:$('auto-improve').checked,addressMode:$('new-address-mode')?.value||'new_domain',hostname:$('new-domain')?.value.trim()||'',autoPublish:$('auto-publish')?.checked!==false});location.href=x.project.kind==='chatroom'?url(x.project.id):'/?screen=publication&business='+encodeURIComponent(x.project.id)}if(form.id==='connect-form'){const key=$('groq-key').value.trim(),provider=$('api-provider').value,pricing={mode:$('billing-mode').value},input={key,provider,pricing};if(pricing.mode==='metered')for(const name of ['managerInput','managerOutput','workerInput','workerOutput'])pricing[name]=$('rate-'+name).value.trim()===''?null:Number($('rate-'+name).value);if(account.connected&&provider===(account.provider||'groq')&&!key){input.managerModel=$('manager-model').value;input.workerModel=$('worker-model').value}const submitEpoch=routeEpoch,x=await api('settings','POST',input);if(submitEpoch!==routeEpoch)return;account={...account,...x};$('groq-key').value='';connectPage();toast(providerName()+' connected. Choose models and cost tracking below.')}if(form.id==='goal-form'){await control('goal',{goal:$('new-goal-text').value.trim()});closeModal()}if(form.id==='contact-form'){await api('projects/'+id+'/inquiries','POST',{name:$('contact-name').value.trim(),email:$('contact-email').value.trim(),message:$('contact-message').value.trim()});modal('<h2 id="modal-title">Inquiry saved.</h2><p class="modal-note">It is now in this project’s inbox. No email was sent.</p><button class="primary" id="close-modal">Done ✓</button>')}}catch(er){if(submitEpoch!==routeEpoch)return;if(form.id==='chat-form'&&$('chat-error'))$('chat-error').textContent=er.message;else if(form.id==='email-setup-form'&&$('resend-error'))$('resend-error').textContent=er.message;else if($('form-error'))$('form-error').textContent=er.message;else toast(er.message)}finally{pendingForms.delete(form);if(b)b.disabled=false}});
document.addEventListener('keydown',event=>{if(!$('workspace-root'))return;if(event.key==='Escape')closeModal();if(event.key==='Tab'&&$('modal-root').firstChild){const items=Array.from($('modal-root').querySelectorAll('button,input,textarea,select,a[href]')).filter(el=>!el.disabled),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
document.addEventListener('pointerdown',event=>{const node=event.target.closest('#team-office .agent');if(!node||!project||project.readOnly||event.button!==0)return;drag={node,id:node.dataset.agent,rect:node.closest('.office').getBoundingClientRect(),startX:event.clientX,startY:event.clientY,moved:false};dragged=false;node.setPointerCapture(event.pointerId)});
document.addEventListener('pointermove',event=>{if(!drag)return;if(Math.hypot(event.clientX-drag.startX,event.clientY-drag.startY)<5&&!drag.moved)return;drag.moved=true;dragged=true;drag.node.classList.add('dragging');const x=Math.max(10,Math.min(90,(event.clientX-drag.rect.left)/drag.rect.width*100)),y=Math.max(17,Math.min(82,(event.clientY-drag.rect.top)/drag.rect.height*100));drag.node.style.setProperty('--x',x);drag.node.style.setProperty('--y',y);drag.position={x,y}});
document.addEventListener('pointerup',async()=>{if(!drag)return;const d=drag;drag=null;if(d.moved){try{project=(await api('projects/'+id+'/layout','POST',{agent:d.id,...d.position})).project;lastRender='';renderProject()}catch(er){toast(er.message)}}setTimeout(()=>dragged=false,50)});document.addEventListener('pointercancel',()=>{drag=null;dragged=false});
window.addEventListener('beforeunload',()=>{clearInterval(ticker);clearInterval(clock)});boot();

let approvals=[],shareData=null,lastPageRecorded='';
function recordPageActivity(){if(!account.signedIn)return;const screen=id?(view==='business'?'business':'team'):(params.get('screen')||'dashboard');const marker=screen+':'+(id||'');if(marker===lastPageRecorded)return;lastPageRecorded=marker;api('activity','POST',{screen,...(id?{projectId:id}:{})}).catch(()=>{})}
function suspendedPage(){$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><h1>Account suspended.</h1><p>Contact the site owner to request a review.</p><a class="secondary" href="/">SOMAS overview</a></section></main>`}
function verificationPage(){$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="connect-box membership-box"><span class="overline">CONFIRM YOUR EMAIL</span><h1>Verify your account.</h1><p>Send a code to <b>${esc(account.verificationEmail||account.user?.email||'the email from your sign-in')}</b>.</p><p>Workspace access starts after you verify this inbox.</p>${!account.mailConfigured?'<p class="setup-notice">Email delivery is not connected. '+(account.canConfigureEmail?'Connect a sender below, then request your code.':'The site owner needs to connect a sender before you can verify.')+'</p>':''}${account.canConfigureEmail?'<a class="text-button" href="?screen=email-setup">Email delivery settings ↗</a>':''}<button class="secondary" id="send-verification" ${account.mailConfigured?'':'disabled'}>${verificationChallenge?'Send another code':'Send verification code'}</button>${verificationChallenge?`${verificationChallenge.message?'<p class="brief-error" role="alert">'+esc(verificationChallenge.message)+'</p>':''}<p class="modal-note">${verificationChallenge.delivery==='accepted'?'Email accepted by the provider. Check your inbox and spam folder.':'The code email is queued or was previously requested.'} Expires ${new Date(verificationChallenge.expires).toLocaleTimeString()}.</p><form id="verify-email-form"><div class="field"><label for="verification-code">8-digit code</label><input id="verification-code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">Verify & continue</button></form>`:''}<p class="modal-note">SOMAS keeps an activity log of account actions, project changes, feedback, and sharing actions. Managers can review these records. Keys, codes, passwords, and typed drafts are excluded.</p><a class="text-button" href="/">← Our two ideas</a></section></main>`}
async function managerPage(){if(!account.signedIn){$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><h1>Human Manager.</h1><p>Sign in, verify your email, then request the owner’s approval.</p><a class="primary" href="${signIn()}" target="_top">Sign in with email</a></section></main>`;return}const epoch=routeEpoch,x=await api('manager-request');if(epoch!==routeEpoch)return;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="connect-box membership-box"><span class="overline">HUMAN ADMINISTRATION</span><h1>${account.isOwner?'You are the owner.':account.isAdmin?'You are a Manager.':'Apply as a Manager.'}</h1><p>Human Managers can review users, projects, opinions and activity, suspend ordinary users, and pause or resume projects. Only the owner approves or revokes Manager roles.</p>${account.isAdmin?'<a class="primary" href="?screen=users">Manage users ↗</a>':!account.emailVerified?'<p>Manager applications also require proof of your contact email.</p><a class="primary" href="?screen=verify">Verify contact email</a>':`<p class="setup-notice">Your request is reviewed by the site owner. The approval code goes only to the owner’s inbox.</p>${x.request?`<p>Latest request: <b>${esc(x.request.status)}</b></p>`:''}<form id="manager-request-form"><div class="field"><label for="manager-reason">Why do you need Manager access?</label><textarea id="manager-reason" minlength="10" maxlength="1000" rows="4" required></textarea></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit" ${account.mailConfigured?'':'disabled'}>Request owner approval</button></form>${!account.mailConfigured?'<p class="modal-note">The owner must configure email delivery first.</p>':''}`}</section></main>`}
async function approvalsPage(){if(!account.isOwner){accessDenied();return}const epoch=routeEpoch,x=await api('admin/manager-requests');if(epoch!==routeEpoch)return;approvals=x.requests;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><span class="overline">OWNER ONLY</span><h1>Manager requests.</h1><p>Verify the applicant’s identity before granting administrative access. Enter the code from your owner inbox on the matching request.</p><div class="report-list">${approvals.map(r=>`<article><h2>${esc(r.name)}</h2><p>${esc(r.email)}</p><p>${esc(r.reason)}</p><small>User ${esc(r.applicant)} · ${esc(r.status)} · ${new Date(r.created).toLocaleString()}</small>${r.status==='pending'?`<div class="user-actions"><button class="primary" data-approval="${esc(r.id)}" ${r.expires>Date.now()?'':'disabled'}>Review & approve</button><button class="secondary" data-reject="${esc(r.id)}">Reject</button><small>${r.expires>Date.now()?'Code expires '+new Date(r.expires).toLocaleTimeString():'Expired — applicant must request a new code.'}</small></div>`:''}</article>`).join('')||'<p>No manager requests.</p>'}</div></section></main>`}
function approvalModal(requestId){const r=approvals.find(x=>x.id===requestId);if(!r)return;modal(`<span class="overline">GRANT MANAGER ACCESS</span><h2 id="modal-title">Approve ${esc(r.name)}?</h2><p>${esc(r.email)} · User ${esc(r.applicant)}</p><p>This grants user management, activity access and service operations. This is not an AI agent role.</p><form id="manager-approval-form" data-request="${esc(r.id)}"><div class="field"><label for="approval-code">Code from your owner inbox</label><input id="approval-code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">Approve this applicant</button></form>`)}
async function activityPage(more=false){if(!account.isAdmin){accessDenied();return}const epoch=routeEpoch,who=params.get('user')||'',query=new URLSearchParams();if(who)query.set('user',who);if(more&&activityCursor)query.set('cursor',activityCursor);const x=await api('admin/activity?'+query);if(epoch!==routeEpoch)return;activityRows=more?[...activityRows,...x.events]:x.events;activityCursor=x.next;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><span class="overline">ACCOUNTABILITY</span><h1>User activity.</h1><p>Account actions, page visits, project controls, provider changes, opinions and share-button actions. Keys, codes, private message bodies and typed drafts are not logged. ${who?'Filtered to user '+esc(who)+'.':''}</p><button class="secondary" id="activity-refresh">Refresh activity</button><a class="text-button" href="?screen=users">← Users</a>${who?'<a class="text-button" href="?screen=activity">All users</a>':''}<div class="activity-table"><table><thead><tr><th>When</th><th>User</th><th>Action</th><th>Resource</th><th>Result</th></tr></thead><tbody>${activityRows.map(e=>`<tr><td>${new Date(e.created).toLocaleString()}</td><td>${esc(e.name||e.actor)}</td><td>${esc(e.action)}</td><td>${esc(e.resource)}</td><td>${e.status}</td></tr>`).join('')}</tbody></table></div>${!activityRows.length?'<p>No recorded activity yet.</p>':''}${activityCursor?'<button class="secondary" id="activity-more">Load more</button>':''}</section></main>`}
async function mailPage(){if(!account.isOwner){accessDenied();return}const epoch=routeEpoch,x=await api('admin/mail');if(epoch!==routeEpoch)return;$('app').innerHTML=`<main class="dashboard">${topbar()}<section class="management-page"><span class="overline">OWNER EMAIL</span><h1>Email delivery.</h1><p>${x.configured?'Sender configured. “Accepted” means the provider accepted the email; it does not confirm arrival in the inbox.':'Sender not configured. Opinion notifications are saved for delivery after setup.'}</p><a class="secondary" href="?screen=email-setup">Sender settings ↗</a><button class="secondary" id="retry-mail" ${x.configured?'':'disabled'}>Retry queued emails</button><div class="activity-table"><table><thead><tr><th>When</th><th>Type</th><th>Status</th><th>Attempts</th></tr></thead><tbody>${x.notifications.map(n=>`<tr><td>${new Date(n.created).toLocaleString()}</td><td>${esc(n.kind)}</td><td>${esc(n.status)}</td><td>${n.attempts}</td></tr>`).join('')}</tbody></table></div></section></main>`}
async function shareModal(){const {shareKit}=await import('/share-content.mjs');shareData=shareKit(location.origin);modal(`<span class="overline">SPREAD THE IDEA</span><h2 id="modal-title">Share SOMAS.</h2><p>We prepare the explanation. You review and publish.</p><div class="field"><label for="share-text">Ready-to-use explanation</label><textarea id="share-text" rows="6" readonly>${esc(shareData.caption)}</textarea></div><button class="primary" id="copy-share">Copy explanation</button><div class="share-links">${shareData.channels.map(c=>`<a class="secondary" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer" data-share-channel="${c.id}"><b>${c.name}</b><small>${c.mode}</small></a>`).join('')}</div><p class="modal-note">Facebook shares the public link; paste the explanation into your post. Instagram requires an image or video; YouTube requires a video. These buttons do not publish automatically.</p>`)}
async function copyShare(){try{await navigator.clipboard.writeText(shareData.caption);toast('Explanation copied. Review and publish on your chosen platform.')}catch{$('share-text')?.select();toast('Select and copy the explanation above.')}}

async function emailSetupPage(){
 if(!account.canConfigureEmail){ownerSetupGate();return}
 const epoch=routeEpoch,x=await api('email-setup');if(epoch!==routeEpoch)return;
 const gmailErrors={wrong_mailbox:'Choose williamkevin999999@gmail.com in Google’s account picker.',gmail_permission:'Approve the send-email permission and enable Gmail API, then reconnect.',provider_unavailable:'First register the Google app below.',access_denied:'Google connection cancelled. Nothing was changed.',owner_required:'Use the existing owner ChatGPT account to connect Gmail.',invalid_state:'This connection expired. Click Connect Gmail again.',provider_failed:'Google could not complete the connection. Check your app settings and try again.'};
 const resend=`<p class="modal-note">Send from a domain you verify in Resend. A Gmail address cannot be used as a Resend sender. Only the site owner enters these settings.</p><form id="email-setup-form"><div class="field"><label for="sender-from">Authorized sender address</label><input id="sender-from" name="sender" value="${esc(x.provider==='gmail'?'':x.from)}" maxlength="250" placeholder="SOMAS &lt;notifications@your-domain.com&gt;" required></div><div class="field"><label for="sender-key">Resend API key</label><input id="sender-key" name="sender-key" type="password" autocomplete="off" spellcheck="false" placeholder="re_…" required maxlength="203"></div><p id="resend-error" class="brief-error" role="alert"></p><button class="primary" type="submit">Save Resend sender</button></form>`;
 const gmailAppForm=`<form id="gmail-app-form"><div class="field"><label for="oauth-client-id">Google client ID</label><input id="oauth-client-id" value="${esc(x.googleClientId||'')}" maxlength="300" autocomplete="off" required></div><div class="field"><label for="oauth-client-secret">Google client secret</label><input id="oauth-client-secret" type="password" autocomplete="off" maxlength="2000" ${x.googleConfigured?'placeholder="Leave blank to keep the saved secret"':'required'}></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">Save sending app</button></form>`;
 const gmail=x.googleConfigured?`<a class="primary" href="/api/auth/oauth/google/start?purpose=gmail" target="_top">${x.provider==='gmail'?'Reconnect Gmail':'Connect Gmail'} ↗</a><p class="modal-note">Choose williamkevin999999@gmail.com and allow SOMAS to send email. This permission does not let SOMAS read your inbox.</p>${x.googleManaged?'':'<details class="sender-alternative"><summary>Update Google sending app</summary>'+gmailAppForm+'</details>'}`:`<p class="modal-note">To send directly from williamkevin999999@gmail.com, register a Google web app and approve its send-mail permission once. This connection only sends email; Google sign-in for visitors has been removed.</p><ol class="modal-note"><li>Open <a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noopener noreferrer">Google Auth Platform ↗</a>. Create a project and configure its audience and consent screen.</li><li>Create a <b>Web application</b> client. Add the callback below as an authorized redirect URI.</li><li>Enable <a href="https://console.cloud.google.com/apis/library/gmail.googleapis.com" target="_blank" rel="noopener noreferrer">Gmail API ↗</a>. If the app is in testing, add williamkevin999999@gmail.com as a test user.</li><li>Save the Client ID and secret below, then click Connect Gmail.</li></ol><code class="oauth-callback">${esc(location.origin)}/api/auth/oauth/google/callback</code>${gmailAppForm}`;
 $('app').innerHTML=`<main class="dashboard">${topbar()}<section class="connect-box membership-box"><span class="overline">OWNER EMAIL</span><h1>Email delivery.</h1><p>${independentHosting?'New users verify their email with a code. Returning users log in with their email and password.':'Visitors enter their email, receive an 8-digit code, and enter it to sign in or create an account.'}</p>${params.has('gmail_error')?'<p class="brief-error" role="alert">'+esc(gmailErrors[params.get('gmail_error')]||gmailErrors.provider_failed)+'</p>':''}${x.lastDelivery?.last_error?'<p class="setup-notice"><b>Latest delivery:</b> '+esc(x.lastDelivery.last_error)+'</p>':''}<p class="setup-notice">${x.configured?esc(x.provider==='gmail'?'Gmail connected':'Resend sender saved')+' · '+esc(x.from):'No sender is connected yet.'}</p>${x.managed?'<p>The sender is managed in the Site runtime settings.</p>':x.provider==='gmail'?`${gmail}<details class="sender-alternative"><summary>Use a Resend sender instead</summary>${resend}</details>`:`${resend}<details class="sender-alternative"><summary>Send from my Gmail instead</summary>${gmail}</details>`}${x.configured&&!account.emailVerified?'<button class="secondary" id="send-verification">Send my owner verification code</button>':''}<p class="modal-note">Owner verification and Manager approval go to williamkevin999999@gmail.com. Other users receive codes at their own addresses.</p><a class="text-button" href="?screen=login">Email sign-in page ↗</a><a class="text-button" href="?screen=dashboard">← Dashboard</a></section></main>`;
}

function saveEmailLogin(){try{if(emailLoginChallenge)sessionStorage.setItem(EMAIL_LOGIN_STORAGE,JSON.stringify({email:emailLoginAddress,challenge:emailLoginChallenge}));else sessionStorage.removeItem(EMAIL_LOGIN_STORAGE)}catch{}}
function restoreEmailLogin(){
 if(emailLoginChallenge)return;
 try{const saved=JSON.parse(sessionStorage.getItem(EMAIL_LOGIN_STORAGE));
 if(!saved||typeof saved.email!=='string'||saved.email.length>250||typeof saved.challenge?.id!=='string'||saved.challenge.id.length>100||!Number.isFinite(saved.challenge.expires)||saved.challenge.expires<=Date.now()||saved.challenge.expires>Date.now()+16*60000){sessionStorage.removeItem(EMAIL_LOGIN_STORAGE);return}
 emailLoginAddress=saved.email;emailLoginChallenge=saved.challenge;
 }catch{}
}
async function requestEmailCode(address,extra={}){
 const epoch=routeEpoch,attempt=++emailAttempt,result=await api('auth/email/start','POST',{email:address,...(emailAuthMode==='password'&&emailLoginChallenge?{id:emailLoginChallenge.id}:{}),...extra});
 if(epoch!==routeEpoch||attempt!==emailAttempt||!['login','signup'].includes(params.get('screen')))return false;
 emailLoginAddress=result.email;emailLoginChallenge=result;saveEmailLogin();emailLoginPage();return true;
}
function emailDeliveryHeading(delivery){return delivery==='accepted'?'Check your email.':['queued','sending'].includes(delivery)?'Sending your code.':delivery==='expired'?'This code expired.':['failed','unavailable'].includes(delivery)?'Email could not be sent.':'Delivery not confirmed.'}
function emailDeliveryText(delivery){return delivery==='accepted'?'Your code was accepted for delivery. Check your inbox and spam.':delivery==='expired'?'Request a new code to continue.':delivery==='uncertain'?'The provider did not confirm delivery. Check your inbox before requesting a new code.':['failed','unavailable','pending_setup'].includes(delivery)?'The code could not be sent. Please try again after the owner checks email delivery.':['queued','sending'].includes(delivery)?'We are sending the code to your inbox. You can enter it as soon as it arrives.':'Your code has not been confirmed as sent. We are checking the saved request. You can enter a code if one arrives.'}
function emailLoginPage(){
 clearInterval(ticker);ticker=null;restoreEmailLogin();
 if(emailAuthMode==='password'&&!emailLoginChallenge){passwordLoginPage();return}
 $('app').innerHTML=`<main class="email-signin-page"><a class="brand" href="/">${brand()}</a><section class="email-signin-card"><span class="overline">WELCOME TO SOMAS</span><h1 id="signin-heading">${emailLoginChallenge?emailDeliveryHeading(emailLoginChallenge.delivery):'Your team starts here.'}</h1>${emailLoginChallenge?`<p>Enter the code for <b>${esc(emailLoginAddress)}</b>.</p><p id="email-delivery-state" class="modal-note" role="status">${emailDeliveryText(emailLoginChallenge.delivery)}</p><p id="email-delivery-error" class="brief-error" role="alert">${esc(emailLoginChallenge.message||'')}</p><form id="email-login-verify"><div class="field"><label for="signin-code">Verification code</label><input id="signin-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" placeholder="8-digit code" required></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">Verify →</button></form><div class="email-signin-links"><button class="text-button" id="resend-login-code">Resend code</button><button class="text-button" id="change-login-email">Use another email</button></div><p class="modal-note">Codes expire in 15 minutes. Wait one minute before requesting another. After a resend, use the newest code.</p>`:`<p>Enter your email to receive an 8-digit verification code.</p><form id="email-login-start"><div class="field"><label for="signin-email">Email address</label><input id="signin-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" value="${esc(emailLoginAddress)}" maxlength="250" required></div><p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">Continue →</button></form><p class="modal-note">No password needed.</p>`}</section><a class="text-button" href="/">← Our two ideas</a></main>`;
 if(emailLoginChallenge&&['queued','retry','sending'].includes(emailLoginChallenge.delivery)){ticker=setInterval(pollLoginDelivery,5000);pollLoginDelivery()}
}

async function pollLoginDelivery(){
 if(!emailLoginChallenge||deliveryPolling===emailLoginChallenge.id||!['login','signup'].includes(params.get('screen')))return;
 const epoch=routeEpoch,challengeId=emailLoginChallenge.id;deliveryPolling=challengeId;
 try{const x=await api('auth/email/status','POST',{id:challengeId,email:emailLoginAddress});if(epoch!==routeEpoch||emailLoginChallenge?.id!==challengeId)return;emailLoginChallenge={...emailLoginChallenge,...x};saveEmailLogin();
 if($('email-delivery-error'))$('email-delivery-error').textContent=x.message||'';
 if($('signin-heading'))$('signin-heading').textContent=emailDeliveryHeading(x.delivery);
 if($('email-delivery-state'))$('email-delivery-state').textContent=emailDeliveryText(x.delivery);
 if(!['queued','retry','sending'].includes(x.delivery)){clearInterval(ticker);ticker=null}
 }catch{if(epoch===routeEpoch&&emailLoginChallenge?.id===challengeId&&$('email-delivery-error'))$('email-delivery-error').textContent='Unable to check delivery right now. Your request is saved; we will check again.'}finally{if(deliveryPolling===challengeId)deliveryPolling=null}
}

function passwordLoginPage(){
 const signup=params.get('screen')==='signup',reset=signup&&params.get('reset')==='1';
 $('app').innerHTML=`<main class="email-signin-page"><a class="brand" href="/">${brand()}</a><section class="email-signin-card"><span class="overline">WELCOME TO SOMAS</span><h1>${reset?'Reset your password.':signup?'Create your account.':'Welcome back.'}</h1><p>${reset?'Confirm your email to choose a new password.':signup?'Verify your email once to create your account.':'Log in with your email and password.'}</p><form id="${signup?'password-signup':'password-login'}"><div class="field"><label for="signin-email">Email address</label><input id="signin-email" name="email" type="email" autocomplete="email" value="${esc(emailLoginAddress)}" maxlength="250" required></div><div class="field"><label for="signin-password">${reset?'New password':'Password'}</label><input id="signin-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="12"':''} maxlength="200" required></div>${signup?'<p class="modal-note">Use at least 12 characters.</p>':''}<p id="form-error" class="brief-error" role="alert"></p><button class="primary" type="submit">${signup?'Send verification code':'Log in'} →</button></form><div class="email-signin-links"><a class="text-button" href="?screen=${signup?'login':'signup'}">${signup?'Already have an account? Log in':'Create an account'}</a>${!signup?'<a class="text-button" href="?screen=signup&reset=1">Reset password</a>':''}</div></section><a class="text-button" href="/">← Our two ideas</a></main>`;
}

async function submitPasswordForm(form){
 const epoch=routeEpoch,email=$('signin-email').value.trim(),password=$('signin-password').value;
 if(form.id==='password-login'){
  const result=await api('auth/email/login','POST',{email,password,next:params.get('next')});
  if(epoch!==routeEpoch)return;emailLoginChallenge=null;saveEmailLogin();location.href=result.next;return;
 }
 // Passwords are never put in browser storage or activity records.
 await requestEmailCode(email,{password,flow:params.get('reset')==='1'?'reset':'signup'});
}
function ownerSetupGate(){
 const path=independentHosting?'/?screen=login&next='+encodeURIComponent('/?screen=email-setup'):'/signin-with-chatgpt?return_to='+encodeURIComponent('/?screen=email-setup');
 $('app').innerHTML=`<main class="email-signin-page"><a class="brand" href="/">${brand()}</a><section class="email-signin-card"><span class="overline">OWNER EMAIL SETTINGS</span><h1>Connect email delivery.</h1><p>${independentHosting?'Log in with the configured owner email and password to manage verification email delivery.':'Use the ChatGPT account that owns this website to manage the sender for verification codes.'}</p><a class="primary" href="${path}" target="_top">Open owner email settings ↗</a>${account.signedIn?'<button class="text-button" id="owner-setup-signout">Sign out of this SOMAS account</button>':''}<p class="modal-note">Only the existing site owner can change the sender. ${independentHosting?'New users verify their email during sign-up.':'Visitors sign in using the code sent to their own email.'}</p><a class="text-button" href="/?screen=login">← Back to sign-in</a></section></main>`;
}
